"""API request handling.

Every request must be authenticated before its payload is processed.
"""


def _validate_request(auth_token):
    """Raise ``PermissionError`` when a request is not authenticated."""
    if not is_valid_token(auth_token):
        raise PermissionError("invalid auth token")


def handle_request(data, auth_token):
    """Validate and process an incoming API request."""
    _validate_request(auth_token)
    return process(data)

